import type { Book, Status } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  reading: 'Reading',
  read: 'Read',
  'want-to-read': 'Want to read',
  dnf: 'Did not finish',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'reading':
      return 'status-reading';
    case 'read':
      return 'status-read';
    case 'want-to-read':
      return 'status-want-to-read';
    case 'dnf':
      return 'status-dnf';
  }
}

interface StatusListProps {
  // null = loading; array = loaded
  items: Book[] | null;
}

const STATUS_ORDER: Status[] = ['reading', 'want-to-read', 'read', 'dnf'];

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item skeleton-item">
            <span className="skeleton-pill" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped = STATUS_ORDER.reduce<Record<Status, Book[]>>(
    (acc, status) => {
      acc[status] = items.filter((b) => b.status === status);
      return acc;
    },
    { reading: [], 'want-to-read': [], read: [], dnf: [] },
  );

  return (
    <div className="status-list-groups">
      {STATUS_ORDER.map((status) => {
        const group = grouped[status];
        if (group.length === 0) return null;
        return (
          <section key={status} className={`status-group ${statusColor(status)}`}>
            <h2 className="status-group-heading">{STATUS_LABELS[status]}</h2>
            <ul className="status-list">
              {group.map((book) => (
                <li key={book.id} className="status-list-item">
                  <span className="status-list-title">{book.title}</span>
                  <span className="status-list-author">{book.author}</span>
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

