interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  // Math.ceil avoids under-charging: fractional cents always round up to the next cent
  const displayPrice = Math.ceil(price * 100) / 100;

  return (
    <span className="price-display">
      {originalPrice !== undefined && originalPrice > price && (
        <s className="price-display-original">${(Math.ceil(originalPrice * 100) / 100).toFixed(2)}</s>
      )}
      <span className="price-display-current">${displayPrice.toFixed(2)}</span>
    </span>
  );
}

