import './DataTable.css';

export interface Row {
  id: string;
  [key: string]: string;
}

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const SKELETON_ROW_COUNT = 5;
const SKELETON_COL_COUNT = 3;

function getColumns(rows: Row[]): string[] {
  if (rows.length === 0) return [];
  return Object.keys(rows[0]).filter((key) => key !== 'id');
}

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns = getColumns(rows);
  const skeletonCols = Array.from({ length: SKELETON_COL_COUNT }, (_, i) => i);
  const skeletonRows = Array.from({ length: SKELETON_ROW_COUNT }, (_, i) => i);

  if (loading) {
    return (
      <table className="data-table">
        <thead className="data-table-header">
          <tr>
            {skeletonCols.map((i) => (
              <th key={i} className="data-table-th">
                <span className="data-table-cell-shimmer" />
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {skeletonRows.map((rowIndex) => (
            <tr key={rowIndex}>
              {skeletonCols.map((colIndex) => (
                <td key={colIndex} className="data-table-td">
                  <span className="data-table-cell-shimmer" />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  return (
    <table className="data-table">
      <thead className="data-table-header">
        <tr>
          {columns.map((col) => (
            <th key={col} className="data-table-th">
              {col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            {columns.map((col) => (
              <td key={col} className="data-table-td">
                {row[col]}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

