import type { Status } from '../../types';
import './ChipBar.css';

const CHIP_LABELS: Record<Status, string> = {
  reading: 'Reading',
  read: 'Read',
  'want-to-read': 'Want to read',
  dnf: 'Did not finish',
};

const ALL_STATUSES: Status[] = ['reading', 'read', 'want-to-read', 'dnf'];

interface ChipBarProps {
  selected: Set<Status>;
  onSelectionChange: (next: Set<Status>) => void;
}

export function ChipBar({ selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: Status): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <ul className="chip-bar" role="list">
      {ALL_STATUSES.map((status) => (
        <li key={status}>
          <button
            className="chip-bar-chip"
            aria-pressed={selected.has(status)}
            onClick={() => handleClick(status)}
          >
            {CHIP_LABELS[status]}
          </button>
        </li>
      ))}
    </ul>
  );
}

