  reading: 'Reading',
  read: 'Read',
  'want-to-read': 'Want to read',
  dnf: 'Did not finish',
};

const ALL_STATUSES: Status[] = ['reading', 'read', 'want-to-read', 'dnf'];

// Owns only visual pressed state; grid filtering is wired by the consumer.
export function ChipBar(): JSX.Element {
  const [selected, setSelected] = useState<Set<Status>>(new Set());

  function handleClick(status: Status): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    setSelected(next);
  }

  return (
    <ul className="chip-bar" role="list">
      {ALL_STATUSES.map((status) => (
        <li key={status}>
          <button
            className="chip-bar-chip"
            aria-pressed={selected.has(status)}
            onClick={() => handleClick(status)}
          >
            {CHIP_LABELS[status]}
          </button>
        </li>
      ))}
    </ul>
  );
}

